import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.Objects;

public class Beneficiaries {
    private final String id;
    private final String name;
    private final Disaster disaster;
    private final Map<String, Integer> outstandingNeeds = new HashMap<>();

    public Beneficiaries(String id, String name, Disaster disaster) {
        this.id = requireText(id, "id");
        this.name = requireText(name, "name");
        this.disaster = Objects.requireNonNull(disaster, "disaster");
    }

    public String getId() {
        return id;
    }

    public String getName() {
        return name;
    }

    public Disaster getDisaster() {
        return disaster;
    }

    public int getUrgencyLevel() {
        return disaster.getUrgencyLevel();
    }

    public void setNeed(String itemName, int quantity) {
        String item = requireText(itemName, "itemName");
        if (quantity < 0) {
            throw new IllegalArgumentException("Need quantity cannot be negative.");
        }
        outstandingNeeds.put(item, quantity);
    }

    public int getOutstandingNeed(String itemName) {
        return outstandingNeeds.getOrDefault(requireText(itemName, "itemName"), 0);
    }

    public Map<String, Integer> getOutstandingNeeds() {
        return Collections.unmodifiableMap(new HashMap<>(outstandingNeeds));
    }

    void fulfillNeed(String itemName, int quantity) {
        String item = requireText(itemName, "itemName");
        int outstanding = getOutstandingNeed(item);
        if (quantity <= 0 || quantity > outstanding) {
            throw new IllegalArgumentException("Fulfilled quantity must be positive and no greater than the outstanding need.");
        }
        outstandingNeeds.put(item, outstanding - quantity);
    }

    private static String requireText(String value, String fieldName) {
        if (value == null || value.trim().isEmpty()) {
            throw new IllegalArgumentException(fieldName + " cannot be blank.");
        }
        return value.trim();
    }
}

public class Disaster {
    private final String id;
    private final String name;
    private final int urgencyLevel;

    public Disaster(String id, String name, int urgencyLevel) {
        this.id = requireText(id, "id");
        this.name = requireText(name, "name");
        if (urgencyLevel < 1 || urgencyLevel > 5) {
            throw new IllegalArgumentException("Urgency level must be between 1 and 5.");
        }
        this.urgencyLevel = urgencyLevel;
    }

    public String getId() {
        return id;
    }

    public String getName() {
        return name;
    }

    public int getUrgencyLevel() {
        return urgencyLevel;
    }

    private static String requireText(String value, String fieldName) {
        if (value == null || value.trim().isEmpty()) {
            throw new IllegalArgumentException(fieldName + " cannot be blank.");
        }
        return value.trim();
    }
}

public class Inventory {
    private final String itemName;
    private int quantity;

    public Inventory(String itemName, int quantity) {
        this.itemName = requireText(itemName, "itemName");
        if (quantity < 0) {
            throw new IllegalArgumentException("Inventory quantity cannot be negative.");
        }
        this.quantity = quantity;
    }

    public String getItemName() {
        return itemName;
    }

    public int getQuantity() {
        return quantity;
    }

    public void addStock(int amount) {
        if (amount <= 0) {
            throw new IllegalArgumentException("Stock addition must be positive.");
        }
        quantity = Math.addExact(quantity, amount);
    }

    public void deductStock(int amount) {
        if (amount <= 0) {
            throw new IllegalArgumentException("Stock deduction must be positive.");
        }
        if (amount > quantity) {
            throw new IllegalArgumentException("Cannot deduct more stock than is available.");
        }
        quantity -= amount;
    }

    private static String requireText(String value, String fieldName) {
        if (value == null || value.trim().isEmpty()) {
            throw new IllegalArgumentException(fieldName + " cannot be blank.");
        }
        return value.trim();
    }
}

public class Donations {
    private final String donorName;
    private final String itemName;
    private final int quantity;
    private boolean applied;

    public Donations(String donorName, String itemName, int quantity) {
        this.donorName = requireText(donorName, "donorName");
        this.itemName = requireText(itemName, "itemName");
        if (quantity <= 0) {
            throw new IllegalArgumentException("Donation quantity must be positive.");
        }
        this.quantity = quantity;
    }

    public String getDonorName() {
        return donorName;
    }

    public String getItemName() {
        return itemName;
    }

    public int getQuantity() {
        return quantity;
    }

    public void applyTo(Inventory inventory) {
        if (inventory == null) {
            throw new IllegalArgumentException("Inventory cannot be null.");
        }
        if (!itemName.equalsIgnoreCase(inventory.getItemName())) {
            throw new IllegalArgumentException("Donation item does not match the inventory item.");
        }
        if (applied) {
            throw new IllegalStateException("Donation has already been applied.");
        }
        inventory.addStock(quantity);
        applied = true;
    }

    private static String requireText(String value, String fieldName) {
        if (value == null || value.trim().isEmpty()) {
            throw new IllegalArgumentException(fieldName + " cannot be blank.");
        }
        return value.trim();
    }
}

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Objects;

public class Distribution {
    private final String beneficiaryId;
    private final String beneficiaryName;
    private final String itemName;
    private final int quantity;
    private final int urgencyLevel;

    private Distribution(Beneficiaries beneficiary, String itemName, int quantity) {
        this.beneficiaryId = beneficiary.getId();
        this.beneficiaryName = beneficiary.getName();
        this.itemName = itemName;
        this.quantity = quantity;
        this.urgencyLevel = beneficiary.getUrgencyLevel();
    }

    public String getBeneficiaryId() {
        return beneficiaryId;
    }

    public String getBeneficiaryName() {
        return beneficiaryName;
    }

    public String getItemName() {
        return itemName;
    }

    public int getQuantity() {
        return quantity;
    }

    public int getUrgencyLevel() {
        return urgencyLevel;
    }

    public static List<Distribution> allocate(Inventory inventory, List<Beneficiaries> beneficiaries) {
        Objects.requireNonNull(inventory, "inventory");
        Objects.requireNonNull(beneficiaries, "beneficiaries");

        List<Beneficiaries> prioritized = new ArrayList<>(beneficiaries);
        if (prioritized.contains(null)) {
            throw new IllegalArgumentException("Beneficiary list cannot contain null.");
        }
        prioritized.sort(Comparator.comparingInt(Beneficiaries::getUrgencyLevel)
                .reversed()
                .thenComparing(Beneficiaries::getId));

        List<Distribution> distributions = new ArrayList<>();
        for (Beneficiaries beneficiary : prioritized) {
            int need = beneficiary.getOutstandingNeed(inventory.getItemName());
            int allocated = Math.min(need, inventory.getQuantity());
            if (allocated > 0) {
                inventory.deductStock(allocated);
                beneficiary.fulfillNeed(inventory.getItemName(), allocated);
                distributions.add(new Distribution(beneficiary, inventory.getItemName(), allocated));
            }
            if (inventory.getQuantity() == 0) {
                break;
            }
        }
        return distributions;
    }
}

