public class TestMvcModelRules {
    private static void expectFailure(Runnable action, Class<? extends RuntimeException> expectedType) {
        try {
            action.run();
            throw new AssertionError("Expected " + expectedType.getSimpleName());
        } catch (RuntimeException exception) {
            if (!expectedType.isInstance(exception)) throw exception;
        }
    }

    public static void main(String[] args) {
        Inventory inventory = new Inventory("I1", "Rice", 20, "kg");
        InventoryController controller = new InventoryController();
        UserAccount encoder = new EncoderAccount("E1", "Encoder", "encoder");
        UserAccount official = new BarangayOfficialAccount("O1", "Official", "official");
        Beneficiaries beneficiary = new Beneficiaries("B1", "Household", "Barangay", 4, "Food", null);

        Donations donation = new Donations("D1", "Donor", 5, "2026-10-14", inventory);
        controller.submitDonation(donation, encoder);
        if (inventory.getQuantity() != 20 || donation.getStatus() != TransactionStatus.DRAFT) throw new AssertionError();
        expectFailure(() -> controller.approveDonation(donation, encoder), SecurityException.class);
        controller.approveDonation(donation, official);
        if (inventory.getQuantity() != 25 || donation.getStatus() != TransactionStatus.APPROVED) throw new AssertionError();
        expectFailure(() -> controller.approveDonation(donation, official), IllegalStateException.class);
        if (inventory.getQuantity() != 25) throw new AssertionError("Duplicate approval changed stock");

        Distribution distribution = new Distribution("R1", 7, "2026-10-14", beneficiary, inventory);
        controller.submitDistribution(distribution, encoder);
        expectFailure(() -> controller.approveDistribution(distribution, encoder), SecurityException.class);
        controller.approveDistribution(distribution, official);
        if (inventory.getQuantity() != 18 || distribution.getStatus() != TransactionStatus.APPROVED) throw new AssertionError();

        Distribution rejected = new Distribution("R2", 3, "2026-10-14", beneficiary, inventory);
        controller.submitDistribution(rejected, encoder);
        controller.rejectDistribution(rejected, official);
        if (inventory.getQuantity() != 18 || rejected.getStatus() != TransactionStatus.REJECTED) throw new AssertionError();

        Distribution tooLarge = new Distribution("R3", 19, "2026-10-14", beneficiary, inventory);
        controller.submitDistribution(tooLarge, encoder);
        expectFailure(() -> controller.approveDistribution(tooLarge, official), IllegalArgumentException.class);
        if (inventory.getQuantity() != 18 || tooLarge.getStatus() != TransactionStatus.DRAFT) throw new AssertionError();

        expectFailure(() -> inventory.removeStock(19), IllegalArgumentException.class);
        if (inventory.getQuantity() != 18) throw new AssertionError("Invalid direct stock operation changed quantity");
        expectFailure(() -> inventory.setQuantity(-1), IllegalArgumentException.class);
        System.out.println("MVC model/controller checks passed.");
    }
}
