public class TestExpandedModels {
    private static void expectFailure(Runnable action, Class<? extends RuntimeException> type) {
        try { action.run(); throw new AssertionError("Expected " + type.getSimpleName()); }
        catch (RuntimeException exception) { if (!type.isInstance(exception)) throw exception; }
    }

    public static void main(String[] args) {
        Inventory rice = new Inventory("I1", "Rice", "Food", 10, "packs", 5, "Warehouse A", "2027-01-01");
        Inventory water = new Inventory("I2", "Water", "Water", 30, "liters", 10, "Warehouse B", "2026-12-01");
        if (!rice.getCategory().equals("Food") || !rice.isLowStock() == false) { }
        if (rice.isLowStock() || !rice.getStorageLocation().equals("Warehouse A")) throw new AssertionError("Inventory details incorrect");
        rice.setQuantity(5);
        if (!rice.isLowStock()) throw new AssertionError("Low-stock threshold behavior incorrect");

        UserAccount encoder = new EncoderAccount("E1", "Encoder", "encoder");
        UserAccount official = new BarangayOfficialAccount("O1", "Official", "official");
        Donor donor = new Donor("DR1", "Relief Group", Donor.Type.ORGANIZATION, "Contact", "contact@example.test");
        DonationController donationController = new DonationController();
        Donations donation = donationController.createDonation("DN1", donor, "2026-10-15", "Warehouse A", "REF-D1", encoder);
        donationController.addDonationItem(donation, new TransactionItem(rice, 4), encoder);
        donationController.addDonationItem(donation, new TransactionItem(water, 7), encoder);
        donationController.submitDonation(donation, encoder);
        if (rice.getQuantity() != 5 || water.getQuantity() != 30) throw new AssertionError("Draft donation changed stock");
        donationController.approveDonation(donation, official);
        if (rice.getQuantity() != 9 || water.getQuantity() != 37 || donation.getItems().size() != 2) throw new AssertionError("Multi-item donation failed");
        expectFailure(() -> donation.addItem(new TransactionItem(rice, 1)), IllegalStateException.class);

        Disaster disaster = new Disaster("D1", "Flood", "Flood", "Barangay A", "2026-10-14", "Active");
        disaster.setSeverity("High");
        disaster.setAffectedAreas("Puroks 1 and 2");
        Beneficiaries beneficiary = new BeneficiaryController().registerBeneficiary(
                "B1", "Household", "Purok 1", 4, "Food and water", "Severe", 1, 1, 1, disaster);
        if (beneficiary.getPwdCount() != 1 || !"High".equals(disaster.getSeverity())) throw new AssertionError("Disaster/beneficiary details incorrect");

        DistributionController distributionController = new DistributionController();
        Distribution distribution = distributionController.createDistribution(
                "R1", "2026-10-15", disaster, beneficiary, "Maligaya Elementary School", "RCPT-1", encoder);
        distributionController.addDistributionItem(distribution, new TransactionItem(rice, 3), encoder);
        distributionController.addDistributionItem(distribution, new TransactionItem(water, 12), encoder);
        distributionController.submitDistribution(distribution, encoder);
        distributionController.approveDistribution(distribution, official);
        if (rice.getQuantity() != 6 || water.getQuantity() != 25 || distribution.getItems().size() != 2
                || distribution.getReleasedBy() != official) throw new AssertionError("Multi-item distribution failed");

        Distribution insufficient = distributionController.createDistribution(
                "R2", "2026-10-15", disaster, beneficiary, "Center", "RCPT-2", encoder);
        distributionController.addDistributionItem(insufficient, new TransactionItem(rice, 7), encoder);
        distributionController.addDistributionItem(insufficient, new TransactionItem(water, 1), encoder);
        distributionController.submitDistribution(insufficient, encoder);
        expectFailure(() -> distributionController.approveDistribution(insufficient, official), IllegalArgumentException.class);
        if (rice.getQuantity() != 6 || water.getQuantity() != 25) throw new AssertionError("Failed multi-item approval partially changed stock");

        Audits audit = new Audits("A1", "Stock adjustment", "2026-10-15T10:00", official,
                null, distribution, "R1", "9 packs", "6 packs", "Relief release");
        if (!"Relief release".equals(audit.getReason()) || !"9 packs".equals(audit.getBeforeValue())) throw new AssertionError("Audit details incorrect");
        System.out.println("Expanded model checks passed.");
    }
}
