import java.util.Objects;

public class Beneficiaries {
    private String beneficiaryId;
    private String name;
    private String address;
    private int householdSize;
    private String assistanceRequirements;
    private String damageLevel;
    private int seniorCitizenCount;
    private int infantCount;
    private int pwdCount;
    private Disaster disaster;
    private final List<FamilyMember> familyMembers = new ArrayList<>();
    private FamilyMember householdHead;

    public Beneficiaries(String beneficiaryId, String name, String address, int householdSize,
            String assistanceRequirements, Disaster disaster) {
        this.beneficiaryId = beneficiaryId;
        this.name = name;
        this.address = address;
        setHouseholdSize(householdSize);
        this.assistanceRequirements = assistanceRequirements;
        this.disaster = disaster;
    }

    public String getDamageLevel() {
        return damageLevel;
    }

    public void setDamageLevel(String damageLevel) {
        this.damageLevel = damageLevel;
    }

    public int getSeniorCitizenCount() {
        if (!familyMembers.isEmpty()) {
            return countMembers(MemberCategory.SENIOR);
        }
        return seniorCitizenCount;
    }

    public void setSeniorCitizenCount(int seniorCitizenCount) {
        requireNoFamilyRoster();
        this.seniorCitizenCount = requireNonNegativeCount(seniorCitizenCount, "Senior citizen count");
    }

    public int getInfantCount() {
        if (!familyMembers.isEmpty()) {
            return countMembers(MemberCategory.INFANT);
        }
        return infantCount;
    }

    public void setInfantCount(int infantCount) {
        requireNoFamilyRoster();
        this.infantCount = requireNonNegativeCount(infantCount, "Infant count");
    }

    public int getPwdCount() {
        if (!familyMembers.isEmpty()) {
            return countMembers(MemberCategory.PWD);
        }
        return pwdCount;
    }

    public void setPwdCount(int pwdCount) {
        requireNoFamilyRoster();
        this.pwdCount = requireNonNegativeCount(pwdCount, "PWD count");
    }

    public String getBeneficiaryId() {
        return beneficiaryId;
    }

    public void setBeneficiaryId(String beneficiaryId) {
        this.beneficiaryId = beneficiaryId;
    }

    public String getName() {
        if (householdHead != null) {
            return householdHead.getFullName();
        }
        return name;
    }

    public void setName(String name) {
        if (householdHead != null) {
            householdHead.setFullName(name);
        }
        this.name = name;
    }

    public String getAddress() {
        return address;
    }

    public void setAddress(String address) {
        this.address = address;
    }

    public int getHouseholdSize() {
        if (!familyMembers.isEmpty()) {
            return familyMembers.size();
        }
        return householdSize;
    }

    public void setHouseholdSize(int householdSize) {
        if (!familyMembers.isEmpty()) {
            throw new IllegalStateException("Household size is determined by its family member records.");
        }
        if (householdSize <= 0) {
            throw new IllegalArgumentException("Household size must be positive.");
        }
        this.householdSize = householdSize;
    }

    public String getAssistanceRequirements() {
        return assistanceRequirements;
    }

    public void setAssistanceRequirements(String assistanceRequirements) {
        this.assistanceRequirements = assistanceRequirements;
    }

    public Disaster getDisaster() {
        return disaster;
    }

    public void setDisaster(Disaster disaster) {
        this.disaster = disaster;
    }

    public List<FamilyMember> getFamilyMembers() {
        return Collections.unmodifiableList(new ArrayList<>(familyMembers));
    }

    public FamilyMember getHouseholdHead() {
        return householdHead;
    }

    public void addFamilyMember(FamilyMember member) {
        Objects.requireNonNull(member, "member");
        for (FamilyMember existing : familyMembers) {
            if (existing.getMemberId().equals(member.getMemberId())) {
                throw new IllegalArgumentException("Family member ID already exists in this household.");
            }
        }
        familyMembers.add(member);
    }

    public void setHouseholdHead(String memberId) {
        FamilyMember selected = null;
        for (FamilyMember member : familyMembers) {
            if (member.getMemberId().equals(memberId)) {
                selected = member;
                break;
            }
        }
        if (selected == null) {
            throw new IllegalArgumentException("Household head must be a member of this household.");
        }
        householdHead = selected;
        name = selected.getFullName();
    }

    private int requireNonNegativeCount(int count, String fieldName) {
        if (count < 0) {
            throw new IllegalArgumentException(fieldName + " cannot be negative.");
        }
        return count;
    }

    private int countMembers(MemberCategory category) {
        int count = 0;
        for (FamilyMember member : familyMembers) {
            boolean matches = category == MemberCategory.SENIOR && member.isSeniorCitizen()
                    || category == MemberCategory.INFANT && member.isInfant()
                    || category == MemberCategory.PWD && member.isPersonWithDisability();
            if (matches) {
                count++;
            }
        }
        return count;
    }

    private void requireNoFamilyRoster() {
        if (!familyMembers.isEmpty()) {
            throw new IllegalStateException("Vulnerability counts are determined by family member records.");
        }
    }

    private enum MemberCategory {
        SENIOR,
        INFANT,
        PWD
    }
}

